def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Modified model with quadratic terms for better approximation."""

    a0, a1, a2, a3, a4, a5 = parameters
    return  a0 + a1 * gate_voltage_abs + a2 * (gate_voltage_abs**2) + a3 * drain_voltage_abs + a4 * (drain_voltage_abs**2)
